def parse(v):
    return tuple(int(x) for x in v.split("."))

def breaks(old, new):
    # 메이저가 바뀌면 깨질 수 있다(0.x 는 마이너도)
    o, n = parse(old), parse(new)
    return n[0] != o[0] or (o[0] == 0 and n[1] != o[1])

def support_until(deprecated_major, keep_majors=2):
    # 폐기 예고한 다음 두 메이저까지 유지 → 지워도 되는 첫 메이저
    return deprecated_major + keep_majors + 1

print(breaks("2.3.1", "2.4.0"))  # False
print(breaks("2.3.1", "3.0.0"))  # True
print(support_until(2))          # 5 → 3.x·4.x 까지 유지
